</code></pre> <ol> <li><code>fluent = true</code> gera <code>p.id()</code> ao invés de <code>p.getId()</code>. Requer configuração especial do Jackson para serialização no Redis — ver seção Cache.</li> </ol> product-service/.../ProductService.java<pre><code>@Service
public class ProductService {

    @Autowired
    private ProductRepository productRepository;

    @CachePut(value = "products", key = "#result.id()") // (1)!
    public Product create(Product product) {
        return productRepository.save(new ProductModel(product)).to();
    }

    @Cacheable(value = "products", key = "#id") // (2)!
    public Product findById(String id) {
        return productRepository.findById(id)
            .map(ProductModel::to).orElse(null);
    }

    @CacheEvict(value = "products", key = "#id") // (3)!
    public void delete(String id) {
        productRepository.deleteById(id);
    }

    public List&lt;Product&gt; findAll() {
        return StreamSupport.stream(
            productRepository.findAll().spliterator(), false
        ).map(ProductModel::to).toList();
    }
}
</code></pre> <ol> <li><code>@CachePut</code> — sempre executa e grava o resultado no cache <code>products</code> com a chave sendo o ID do produto criado.</li> <li><code>@Cacheable</code> — retorna do cache se a chave existir; caso contrário busca no banco e armazena.</li> <li><code>@CacheEvict</code> — invalida a entrada do cache ao deletar, evitando servir dados obsoletos.</li> </ol> product-service/.../ProductResource.java<pre><code>@RestController
public class ProductResource implements ProductController {

    @Autowired
    private ProductService productService;

    @Override
    public ResponseEntity&lt;Void&gt; create(ProductIn in) {
        final Product p = productService.create(ProductParser.to(in));
        return ResponseEntity.created(
            ServletUriComponentsBuilder
                .fromCurrentRequest()
                .path("/{id}")
                .buildAndExpand(p.id())
                .toUri()
        ).build(); // (1)!
    }

    @Override
    public ResponseEntity&lt;ProductOut&gt; findById(String id) {
        Product p = productService.findById(id);
        return p == null
            ? ResponseEntity.notFound().build()
            : ResponseEntity.ok(ProductParser.to(p));
    }

    @Override
    public ResponseEntity&lt;Void&gt; delete(String id) {
        productService.delete(id);
        return ResponseEntity.noContent().build();
    }

    @Override
    public ResponseEntity&lt;Void&gt; healthCheck() {
        return ResponseEntity.ok().build();
    }
}
</code></pre> <ol> <li><code>201 Created</code> com header <code>Location: /products/{id}</code> apontando para o recurso criado.</li> </ol>

load-tests/exchange.js<pre><code>const CURRENCY_PAIRS = [
  ['USD', 'BRL'], ['EUR', 'BRL'], ['USD', 'EUR'],
  ['GBP', 'USD'], ['BRL', 'USD'],
];

export default function () {
  const [from, to] = CURRENCY_PAIRS[
    Math.floor(Math.random() * CURRENCY_PAIRS.length)
  ];
  const res = http.get(`${BASE_URL}/exchanges/${from}/${to}`, {
    headers: { 'id-account': 'load-test-account' },
  });
  check(res, { 'status 200': (r) =&gt; r.status === 200 });
  sleep(0.3);
}
</code></pre>

