const cacheMissDuration = new Trend('cache_miss_duration');

export default function (data) {
  const getRes = http.get(`${BASE_URL}/products/${data.productId}`);

  if (__ITER === 0) {
    cacheMissDuration.add(getRes.timings.duration); // (1)!
